  CREATE TEMP TABLE sel_par_refresh_stage ON COMMIT DROP AS
  WITH ids AS (
    SELECT ticker,datum,array_agg(i ORDER BY i) bron_ids
    FROM pg_temp.sel_par_refresh_bron b CROSS JOIN LATERAL unnest(b.selectie_bron_ids) i GROUP BY ticker,datum
  )
  SELECT min(o.id) AS "id",
o."ticker" AS "ticker",
o."datum" AS "datum",
string_agg(DISTINCT o.strategie,' | ' ORDER BY o.strategie) AS "strategie",
CASE WHEN count(DISTINCT to_jsonb(o."beurs")) FILTER(WHERE o."beurs" IS NOT NULL)<=1 THEN (array_agg(o."beurs") FILTER(WHERE o."beurs" IS NOT NULL))[1] END AS "beurs",
