CASE WHEN count(DISTINCT to_jsonb(o."forward_bron_aanwezig")) FILTER(WHERE o."forward_bron_aanwezig" IS NOT NULL)>1 THEN 'forward_bron_aanwezig'::text END,
CASE WHEN count(DISTINCT to_jsonb(o."forward_entry_koers")) FILTER(WHERE o."forward_entry_koers" IS NOT NULL)>1 THEN 'forward_entry_koers'::text END,
CASE WHEN count(DISTINCT to_jsonb(o."forward_bijgewerkt_op")) FILTER(WHERE o."forward_bijgewerkt_op" IS NOT NULL)>1 THEN 'forward_bijgewerkt_op'::text END,
CASE WHEN count(DISTINCT to_jsonb(o."koersbasis_verschil")) FILTER(WHERE o."koersbasis_verschil" IS NOT NULL)>1 THEN 'koersbasis_verschil'::text END,
CASE WHEN count(DISTINCT to_jsonb(o."koers_5d")) FILTER(WHERE o."koers_5d" IS NOT NULL)>1 THEN 'koers_5d'::text END,
