CASE WHEN count(DISTINCT to_jsonb(o."rendement_10d_pct")) FILTER(WHERE o."rendement_10d_pct" IS NOT NULL)>1 THEN 'rendement_10d_pct'::text END,
CASE WHEN count(DISTINCT to_jsonb(o."status_10d")) FILTER(WHERE o."status_10d" IS NOT NULL)>1 THEN 'status_10d'::text END,
CASE WHEN count(DISTINCT to_jsonb(o."koers_20d")) FILTER(WHERE o."koers_20d" IS NOT NULL)>1 THEN 'koers_20d'::text END,
CASE WHEN count(DISTINCT to_jsonb(o."bron_fwd_ret_20d")) FILTER(WHERE o."bron_fwd_ret_20d" IS NOT NULL)>1 THEN 'bron_fwd_ret_20d'::text END,
CASE WHEN count(DISTINCT to_jsonb(o."rendement_20d_pct")) FILTER(WHERE o."rendement_20d_pct" IS NOT NULL)>1 THEN 'rendement_20d_pct'::text END,
CASE WHEN count(DISTINCT to_jsonb(o."status_20d")) FILTER(WHERE o."status_20d" IS NOT NULL)>1 THEN 'status_20d'::text END,
