END $refresh$;
REVOKE ALL ON FUNCTION public.zaai_sel_par(date,boolean,jsonb) FROM PUBLIC,anon,authenticated,service_role;
COMMENT ON FUNCTION public.zaai_sel_par(date,boolean,jsonb) IS 'Beheerfunctie, SECURITY INVOKER. Atomair bijwerken van bestaande sel_par en strategiebron na upstreamcontrole. Eén succesvolle uitvoering per selectiedag, tenzij force. Brontabellen worden niet aangepast. Historische rijen blijven behouden.';
COMMENT ON TABLE public.sel_par_runs IS 'Succesvolle dagelijkse sel_par-verversingen met upstreamstatus; falende transacties schrijven geen succesmarker.';

